use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigSenderNameAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigSenderNameAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getSenderName returns null on a freshly created holder.
         */
        public function testSenderNameNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithSmtpOutboundConfigSenderNameAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isSenderNameAssigned());
            $this->assertNull($holder->getSenderName());
        }
}
